fn grant_subject(principal: &Principal) -> GrantSubject {
    let id = principal
        .identity_id
        .clone()
        .unwrap_or_else(|| principal.key_id.clone());
    match principal.subject_type.as_str() {
        "human" | "user" => GrantSubject::Human(id),
        "agent" => GrantSubject::Agent(id),
        "workload" => GrantSubject::Workload(id),
        "worker" => GrantSubject::Worker(id),
        "connection" => GrantSubject::Connection(id),
        _ => GrantSubject::Service(id),
    }
}
fn authorization_error(error: feltdb::authorization::AuthorizationError) -> ApiError {
    let status = if error.code == "GRANT_INVALID" {
        StatusCode::BAD_REQUEST
    } else {
        StatusCode::FORBIDDEN
    };
    ApiError(
        status,
        serde_json::to_string(&error).unwrap_or(error.message),
    )
}
fn record_authorization_audit(
    state: &AppState,
    principal: &str,
    action: &str,
    target: &str,
    outcome: &str,
    status: u16,
) {
    let _ = state.audit.record(AuditEvent {
        timestamp_ms: 0,
        namespace: &state.namespace,
        principal,
        action,
        target,
        outcome,
        status,
    });
}
async fn check_resource_authorization(
    State(state): State<AppState>,
    Extension(principal): Extension<Principal>,
    Json(mut request): Json<ResourceAuthorizationRequest>,
) -> Result<Json<Value>, ApiError> {
    request.subject = grant_subject(&principal);
    request.context.timestamp = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs() as i64;
    let mut grants = state.grants.lock().map_err(|_| {
        ApiError(
            StatusCode::INTERNAL_SERVER_ERROR,
            "grant store unavailable".into(),
        )
    })?;
    let decision = grants.check(&request, &state.grant_signer);
    let status = if decision.allowed {
        "allowed"
    } else {
        "denied"
    };
    record_authorization_audit(
        &state,
        &principal.key_id,
        "authorization.decision",
        &format!("{}:{}", request.application_id, request.resource.uri),
        status,
        if decision.allowed { 200 } else { 403 },
    );
    Ok(Json(json!(decision)))
}
async fn create_signed_grant(
    State(state): State<AppState>,
    Extension(principal): Extension<Principal>,
    Json(mut grant): Json<Grant>,
) -> Result<(StatusCode, Json<Value>), ApiError> {
    if !principal.permits("authorization:grant") {
        return Err(ApiError(
            StatusCode::FORBIDDEN,
            "authorization:grant required".into(),
        ));
    }
    grant.issuer = grant_subject(&principal);
    let signed = state
        .grants
        .lock()
        .map_err(|_| {
            ApiError(
                StatusCode::INTERNAL_SERVER_ERROR,
                "grant store unavailable".into(),
            )
        })?
        .create(grant, &state.grant_signer)
        .map_err(authorization_error)?;
    record_authorization_audit(
        &state,
        &principal.key_id,
        "grant.created",
        &signed.grant.id,
        "active",
        201,
    );
    Ok((StatusCode::CREATED, Json(json!(signed))))
}
async fn get_signed_grant(
    State(state): State<AppState>,
    Path(id): Path<String>,
) -> Result<Json<Value>, ApiError> {
    let store = state.grants.lock().map_err(|_| {
        ApiError(
            StatusCode::INTERNAL_SERVER_ERROR,
            "grant store unavailable".into(),
        )
    })?;
    store
        .grants
        .get(&id)
        .cloned()
        .map(|v| Json(json!(v)))
        .ok_or_else(|| ApiError(StatusCode::NOT_FOUND, "grant not found".into()))
}
async fn revoke_signed_grant(
    State(state): State<AppState>,
    Extension(principal): Extension<Principal>,
    Path(id): Path<String>,
) -> Result<Json<Value>, ApiError> {
    if !principal.permits("authorization:grant") {
        return Err(ApiError(
            StatusCode::FORBIDDEN,
            "authorization:grant required".into(),
        ));
    }
    let signed = state
        .grants
        .lock()
        .map_err(|_| {
            ApiError(
                StatusCode::INTERNAL_SERVER_ERROR,
                "grant store unavailable".into(),
            )
        })?
        .revoke(&id, &state.grant_signer)
        .map_err(authorization_error)?;
    record_authorization_audit(
        &state,
        &principal.key_id,
        "grant.revoked",
        &id,
        "revoked",
        200,
    );
    Ok(Json(json!(signed)))
}
#[derive(Deserialize)]
struct DelegateGrantRequest {
    grant: Grant,
}
async fn delegate_signed_grant(
    State(state): State<AppState>,
    Extension(principal): Extension<Principal>,
    Path(id): Path<String>,
    Json(mut input): Json<DelegateGrantRequest>,
) -> Result<(StatusCode, Json<Value>), ApiError> {
    if !principal.permits("authorization:grant") {
        return Err(ApiError(
            StatusCode::FORBIDDEN,
            "authorization:grant required".into(),
        ));
    }
    input.grant.issuer = grant_subject(&principal);
    let signed = state
        .grants
        .lock()
        .map_err(|_| {
            ApiError(
                StatusCode::INTERNAL_SERVER_ERROR,
                "grant store unavailable".into(),
            )
        })?
        .delegate(input.grant, &id, &state.grant_signer)
        .map_err(authorization_error)?;
    record_authorization_audit(
        &state,
        &principal.key_id,
        "grant.delegated",
        &signed.grant.id,
        &format!("parent:{id}"),
        201,
    );
    Ok((StatusCode::CREATED, Json(json!(signed))))
}
async fn get_authorization_decision(
    State(state): State<AppState>,
    Path(id): Path<String>,
) -> Result<Json<Value>, ApiError> {
    let store = state.grants.lock().map_err(|_| {
        ApiError(
            StatusCode::INTERNAL_SERVER_ERROR,
            "grant store unavailable".into(),
        )
    })?;
    store
        .decisions
        .get(&id)
        .cloned()
        .map(|v| Json(json!(v)))
        .ok_or_else(|| {
            ApiError(
                StatusCode::NOT_FOUND,
                "authorization decision not found".into(),
            )
        })
}
async fn get_authorization_verification_key(State(state): State<AppState>) -> Json<Value> {
    Json(
        json!({"algorithm":"ED25519-V1","key_id":"feltdb-primary-v1","public_key":state.grant_signer.public_key_hex()}),
    )
}

#[derive(Deserialize)]
struct CreateSyncSessionRequest {
    device: DeviceIdentity,
    scope: SyncScope,
    offline_grant: feltdb::authorization::SignedGrant,
}
#[derive(Deserialize)]
struct PullSyncRequest {
    session_id: String,
    cursor: SyncCursor,
    #[serde(default = "sync_limit")]
    limit: usize,
}
#[derive(Deserialize)]
struct AckSyncRequest {
    session_id: String,
    cursor: SyncCursor,
}
#[derive(Deserialize)]
struct CloseSyncRequest {
    session_id: String,
}
fn sync_limit() -> usize {
    250
}
fn sync_error(error: feltdb::sync_contract::SyncError) -> ApiError {
    let status = match error.code.as_str() {
        "SYNC_CURSOR_SCOPE_DENIED" | "SYNC_SCOPE_DENIED" | "SYNC_UNAUTHORIZED" => {
            StatusCode::FORBIDDEN
        }
        "SYNC_SESSION_INVALID" => StatusCode::NOT_FOUND,
        "SYNC_LEASE_HELD" => StatusCode::CONFLICT,
        _ => StatusCode::UNPROCESSABLE_ENTITY,
    };
    ApiError(
        status,
        serde_json::to_string(&error).unwrap_or(error.message),
    )
}
fn unix_seconds_i64() -> i64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs() as i64
}
async fn create_sync_session(
    State(state): State<AppState>,
    Extension(principal): Extension<Principal>,
    Json(mut input): Json<CreateSyncSessionRequest>,
) -> Result<(StatusCode, Json<Value>), ApiError> {
    input.device.subject = grant_subject(&principal);
    application_scope(
        &state,
        &principal.key_id,
        &input.device.application_id,
        "state:read",
    )?;
    state
        .grant_signer
        .verify_signature(&input.offline_grant)
        .map_err(authorization_error)?;
    let now = unix_seconds_i64();
    let session = state
        .sync
        .lock()
        .map_err(|_| {
            ApiError(
                StatusCode::INTERNAL_SERVER_ERROR,
                "sync store unavailable".into(),
            )
        })?
        .create_session(input.device, input.scope, &input.offline_grant, now)
        .map_err(sync_error)?;
    record_authorization_audit(
        &state,
        &principal.key_id,
        "sync.session.created",
        &session.session_id,
        "active",
        201,
    );
    Ok((StatusCode::CREATED, Json(json!(session))))
}
async fn push_sync(
    State(state): State<AppState>,
    Extension(principal): Extension<Principal>,
    Json(batch): Json<SyncBatch>,
) -> Result<Json<Value>, ApiError> {
    let now = unix_seconds_i64();
    let session: SyncSession = {
        state
            .sync
            .lock()
            .map_err(|_| {
                ApiError(
                    StatusCode::INTERNAL_SERVER_ERROR,
                    "sync store unavailable".into(),
                )
            })?
            .session(&batch.session_id, now)
            .map_err(sync_error)?
            .clone()
    };
    if session.device.subject != grant_subject(&principal) {
        return Err(ApiError(
            StatusCode::FORBIDDEN,
            "sync session belongs to another subject".into(),
        ));
    }
    let mut acknowledgements = vec![];
    let mut rejections = vec![];
    let mut conflicts = vec![];
    for mut operation in batch.operations {
        operation.authorization_context.timestamp = now;
        if let Err(error) = operation.validate_identity() {
            rejections.push(SyncRejection {
                operation_id: operation.operation_id,
                code: error.code,
                message: error.message,
                retryable: false,
            });
            continue;
        }
        if operation.tenant_id != session.device.tenant_id
            || operation.application_id != session.device.application_id
            || operation.subject != session.device.subject
            || operation.device_id != session.device.device_id
            || !session.scope.contains(&operation.resource.uri)
        {
            rejections.push(SyncRejection {
                operation_id: operation.operation_id,
                code: "SYNC_SCOPE_DENIED".into(),
                message: "operation does not belong to this session projection".into(),
                retryable: false,
            });
            continue;
        }
        if let Some(position) = state
            .sync
            .lock()
            .map_err(|_| {
                ApiError(
                    StatusCode::INTERNAL_SERVER_ERROR,
                    "sync store unavailable".into(),
                )
            })?
            .committed(&operation.operation_id)
        {
            acknowledgements.push(SyncAck {
                operation_id: operation.operation_id,
                outcome: ReconciliationOutcome::AlreadyCommitted,
                server_position: Some(position),
                transaction_id: None,
                decision_id: None,
            });
            continue;
        }
        let auth_request = ResourceAuthorizationRequest {
            subject: operation.subject.clone(),
            tenant_id: operation.tenant_id.clone(),
            application_id: operation.application_id.clone(),
            resource: operation.resource.clone(),
            capability: "state:write".into(),
            context: operation.authorization_context.clone(),
            grant_id: Some(operation.offline_grant.grant.id.clone()),
            subject_attributes: BTreeMap::new(),
        };
        let decision = {
            let grants = state.grants.lock().map_err(|_| {
                ApiError(
                    StatusCode::INTERNAL_SERVER_ERROR,
                    "grant store unavailable".into(),
                )
            })?;
            authorize_resource(
                &auth_request,
                Some(&operation.offline_grant),
                &state.grant_signer,
                &grants.grants,
                &grants.revocations,
            )
        };
        if !decision.allowed {
            rejections.push(SyncRejection {
                operation_id: operation.operation_id,
                code: "SYNC_UNAUTHORIZED".into(),
                message: decision.reason,
                retryable: false,
            });
            continue;
        }
        let target_revision = state
            .applications
            .pointers(&operation.application_id)
            .get("production")
            .cloned()
            .unwrap_or_else(|| operation.application_revision.clone());
        let Some(revision) = state.applications.revision(
            &operation.tenant_id,
            &operation.application_id,
            &target_revision,
        ) else {
            rejections.push(SyncRejection {
                operation_id: operation.operation_id,
                code: "SYNC_SCHEMA_MISMATCH".into(),
                message: "authoritative revision not found".into(),
                retryable: true,
            });
            continue;
        };
        let schema = schema_from_revision(&revision);
        if operation.schema_version != schema.schema_version {
            let compatibility = state
                .applications
                .revision(
                    &operation.tenant_id,
                    &operation.application_id,
                    &operation.application_revision,
                )
                .map(|client| {
                    compare_schemas(&schema_from_revision(&client), &schema).classification
                });
            if !matches!(
                compatibility,
                Some(feltdb::state_contract::SchemaCompatibility::Safe)
            ) {
                let (code, retryable) = if matches!(
                    compatibility,
                    Some(feltdb::state_contract::SchemaCompatibility::RequiresMigration)
                ) {
                    ("SYNC_SCHEMA_MIGRATION_REQUIRED", true)
                } else {
                    ("SYNC_SCHEMA_MISMATCH", false)
                };
                rejections.push(SyncRejection {
                    operation_id: operation.operation_id,
                    code: code.into(),
                    message: format!(
                        "client schema {} cannot be safely applied to server schema {}",
                        operation.schema_version, schema.schema_version
                    ),
                    retryable,
                });
                continue;
            }
        }
        let latest = {
            state
                .sync
                .lock()
                .map_err(|_| {
                    ApiError(
                        StatusCode::INTERNAL_SERVER_ERROR,
                        "sync store unavailable".into(),
                    )
                })?
                .operations
                .iter()
                .rev()
                .find(|stored| stored.operation.resource.uri == operation.resource.uri)
                .cloned()
        };
        if let Some(latest) = latest {
            if operation.causal_context.get("server").copied().unwrap_or(0) < latest.position {
                conflicts.push(SyncConflict {
                    operation_id: operation.operation_id,
                    resource: operation.resource.uri,
                    local_causal_context: operation.causal_context,
                    server_causal_context: [("server".into(), latest.position)].into(),
                    reason: "concurrent resource mutation requires explicit reconciliation".into(),
                });
                continue;
            }
        }
        if state
            .sync
            .lock()
            .map_err(|_| {
                ApiError(
                    StatusCode::INTERNAL_SERVER_ERROR,
                    "sync store unavailable".into(),
                )
            })?
            .tombstones
            .get(&operation.resource.uri)
            .is_some_and(|t| {
                t.deletion_operation != operation.operation_id
                    && !matches!(operation.operation.kind, TransactionOperationKind::Delete)
            })
        {
            rejections.push(SyncRejection {
                operation_id: operation.operation_id,
                code: "SYNC_STALE".into(),
                message: "a retained tombstone prevents stale resurrection".into(),
                retryable: false,
            });
            continue;
        }
        let transaction = TransactionRequest {
            transaction_id: Some(operation.operation_id.clone()),
            tenant_id: operation.tenant_id.clone(),
            application_id: operation.application_id.clone(),
            revision_id: revision.revision_id.clone(),
            schema_version: schema.schema_version,
            state_namespace: Some(format!(
                "application:{}:production",
                operation.application_id
            )),
            causal_parent: operation.causal_context.get("server").copied(),
            authorization: state_authorization_legacy(
                &principal,
                &operation.tenant_id,
                &operation.application_id,
                &revision.revision_id,
                "state:write",
            ),
            operations: vec![operation.operation.clone()],
            preconditions: vec![],
        };
        let _transaction_permit = state
            .state_transaction_admission
            .acquire()
            .await
            .expect("transaction admission is never closed");
        match execute_transaction(&state.db, &schema, &transaction, None) {
            Ok(committed) => {
                let position = state
                    .sync
                    .lock()
                    .map_err(|_| {
                        ApiError(
                            StatusCode::INTERNAL_SERVER_ERROR,
                            "sync store unavailable".into(),
                        )
                    })?
                    .record(
                        operation.clone(),
                        ReconciliationOutcome::Accept,
                        Some(decision.decision_id.clone()),
                        now,
                    )
                    .map_err(sync_error)?;
                record_authorization_audit(
                    &state,
                    &principal.key_id,
                    "sync.operation.accepted",
                    &operation.operation_id,
                    "accepted",
                    201,
                );
                acknowledgements.push(SyncAck {
                    operation_id: operation.operation_id,
                    outcome: if committed.duplicate {
                        ReconciliationOutcome::AlreadyCommitted
                    } else {
                        ReconciliationOutcome::Accept
                    },
                    server_position: Some(position),
                    transaction_id: Some(committed.transaction_id),
                    decision_id: Some(decision.decision_id),
                });
            }
            Err(error) => {
                let retryable =
                    matches!(error.code.as_str(), "STORAGE_FAILURE" | "STATE_UNAVAILABLE");
                rejections.push(SyncRejection {
                    operation_id: operation.operation_id,
                    code: error.code,
                    message: error.message,
                    retryable,
                });
            }
        }
    }
    let mut cursor = session.cursor.clone();
    if let Some(max) = acknowledgements
        .iter()
        .filter_map(|v| v.server_position)
        .max()
    {
        cursor.position = cursor.position.max(max);
    }
    Ok(Json(json!(SyncResult {
        acknowledgements,
        rejections,
        conflicts,
        cursor
    })))
}
async fn pull_sync(
    State(state): State<AppState>,
    Extension(principal): Extension<Principal>,
    Json(input): Json<PullSyncRequest>,
) -> Result<Json<Value>, ApiError> {
    let now = unix_seconds_i64();
    let (operations, cursor) = state
        .sync
        .lock()
        .map_err(|_| {
            ApiError(
                StatusCode::INTERNAL_SERVER_ERROR,
                "sync store unavailable".into(),
            )
        })?
        .pull(&input.session_id, &input.cursor, input.limit, now)
        .map_err(sync_error)?;
    let session = {
        state
            .sync
            .lock()
            .unwrap()
            .session(&input.session_id, now)
            .map_err(sync_error)?
            .clone()
    };
    if session.device.subject != grant_subject(&principal) {
        return Err(ApiError(
            StatusCode::FORBIDDEN,
            "sync session belongs to another subject".into(),
        ));
    }
    let grants = state.grants.lock().map_err(|_| {
        ApiError(
            StatusCode::INTERNAL_SERVER_ERROR,
            "grant store unavailable".into(),
        )
    })?;
    let signed = grants.grants.get(&session.grant_id).ok_or_else(|| {
        ApiError(
            StatusCode::FORBIDDEN,
            "sync grant is no longer active".into(),
        )
    })?;
    for stored in &operations {
        let request = ResourceAuthorizationRequest {
            subject: session.device.subject.clone(),
            tenant_id: session.device.tenant_id.clone(),
            application_id: session.device.application_id.clone(),
            resource: stored.operation.resource.clone(),
            capability: "state:read".into(),
            context: feltdb::authorization::AuthorizationContext {
                timestamp: now,
                ..Default::default()
            },
            grant_id: Some(session.grant_id.clone()),
            subject_attributes: BTreeMap::new(),
        };
        let decision = authorize_resource(
            &request,
            Some(signed),
            &state.grant_signer,
            &grants.grants,
            &grants.revocations,
        );
        if !decision.allowed {
            return Err(ApiError(StatusCode::FORBIDDEN, decision.reason));
        }
    }
    Ok(Json(json!({"operations":operations,"cursor":cursor})))
}
async fn acknowledge_sync(
    State(state): State<AppState>,
    Extension(principal): Extension<Principal>,
    Json(input): Json<AckSyncRequest>,
) -> Result<Json<Value>, ApiError> {
    let checkpoint = state
        .sync
        .lock()
        .map_err(|_| {
            ApiError(
                StatusCode::INTERNAL_SERVER_ERROR,
                "sync store unavailable".into(),
            )
        })?
        .acknowledge(&input.session_id, input.cursor, unix_seconds_i64())
        .map_err(sync_error)?;
    record_authorization_audit(
        &state,
        &principal.key_id,
        "sync.cursor.advanced",
        &input.session_id,
        "acknowledged",
        200,
    );
    Ok(Json(json!(checkpoint)))
}
async fn close_sync(
    State(state): State<AppState>,
    Json(input): Json<CloseSyncRequest>,
) -> Result<StatusCode, ApiError> {
    state
        .sync
        .lock()
        .map_err(|_| {
            ApiError(
                StatusCode::INTERNAL_SERVER_ERROR,
                "sync store unavailable".into(),
            )
        })?
        .close(&input.session_id)
        .map_err(sync_error)?;
    Ok(StatusCode::NO_CONTENT)
}
async fn sync_status(
    State(state): State<AppState>,
    Extension(principal): Extension<Principal>,
) -> Result<Json<Value>, ApiError> {
    let store = state.sync.lock().map_err(|_| {
        ApiError(
            StatusCode::INTERNAL_SERVER_ERROR,
            "sync store unavailable".into(),
        )
    })?;
    let subject = grant_subject(&principal);
    Ok(Json(
        json!({"sessions":store.sessions.values().filter(|v|v.device.subject==subject).collect::<Vec<_>>(),"checkpoints":store.checkpoints.values().collect::<Vec<_>>(),"operations":store.operations.len(),"tombstones":store.tombstones.len()}),
    ))
}

