fn workload_error(error: feltdb::workload::WorkloadError) -> ApiError {
    let status = match error.code.as_str() {
        "WORKLOAD_NOT_FOUND" => StatusCode::NOT_FOUND,
        "WORKLOAD_STALE_FENCE"
        | "WORKLOAD_TRANSITION_DENIED"
        | "WORKLOAD_NOT_READY"
        | "WORKLOAD_NOT_YET_ELIGIBLE" => StatusCode::CONFLICT,
        "WORKLOAD_UNAUTHORIZED" | "WORKLOAD_CAPABILITY_DENIED" => StatusCode::FORBIDDEN,
        "WORKLOAD_STORAGE_FAILURE" => StatusCode::SERVICE_UNAVAILABLE,
        _ => StatusCode::UNPROCESSABLE_ENTITY,
    };
    ApiError(
        status,
        serde_json::to_string(&error).unwrap_or(error.message),
    )
}
fn worker_error(error: feltdb::worker_mesh::WorkerMeshError) -> ApiError {
    let status = match error.code.as_str() {
        "WORKER_NOT_FOUND" => StatusCode::NOT_FOUND,
        "WORKER_UNAUTHORIZED"
        | "MESH_PLACEMENT_DENIED"
        | "MESH_CAPABILITY_DENIED"
        | "MESH_CLAIM_SCOPE_DENIED" => StatusCode::FORBIDDEN,
        "WORKER_BUSY" | "WORKER_TRANSITION_DENIED" | "MESH_STALE_FENCE" => StatusCode::CONFLICT,
        "MESH_STORAGE_FAILURE" => StatusCode::SERVICE_UNAVAILABLE,
        _ => StatusCode::UNPROCESSABLE_ENTITY,
    };
    ApiError(
        status,
        serde_json::to_string(&error).unwrap_or(error.message),
    )
}
fn release_worker_claim_projection(state: &AppState, workload_id: &str, worker_id: &str, claim_id: &str) {
    match state.mesh.lock() {
        Ok(mut mesh) => {
            if let Err(error) = mesh.release_claim(worker_id, claim_id) {
                tracing::warn!(%workload_id, %claim_id, %error,
                    "durable work reached a terminal attempt state but the worker mesh projection did not release its claim");
            }
        }
        Err(_) => tracing::warn!(%workload_id, %claim_id,
            "durable work reached a terminal attempt state but the worker mesh projection was unavailable"),
    }
}
fn workload_decision(
    state: &AppState,
    subject: GrantSubject,
    tenant: &str,
    application: &str,
    resource: String,
    capability: &str,
    grant: &feltdb::authorization::SignedGrant,
) -> Result<feltdb::authorization::AuthorizationDecision, ApiError> {
    let request = ResourceAuthorizationRequest {
        subject,
        tenant_id: tenant.into(),
        application_id: application.into(),
        resource: feltdb::authorization::Resource {
            uri: resource,
            attributes: BTreeMap::new(),
        },
        capability: capability.into(),
        context: feltdb::authorization::AuthorizationContext {
            timestamp: unix_seconds_i64(),
            ..Default::default()
        },
        grant_id: Some(grant.grant.id.clone()),
        subject_attributes: BTreeMap::new(),
    };
    let grants = state.grants.lock().map_err(|_| {
        ApiError(
            StatusCode::INTERNAL_SERVER_ERROR,
            "grant store unavailable".into(),
        )
    })?;
    let decision = authorize_resource(
        &request,
        Some(grant),
        &state.grant_signer,
        &grants.grants,
        &grants.revocations,
    );
    if decision.allowed {
        Ok(decision)
    } else {
        Err(ApiError(StatusCode::FORBIDDEN, decision.reason))
    }
}
async fn create_workload(
    State(state): State<AppState>,
    Extension(principal): Extension<Principal>,
    Json(mut input): Json<CreateWorkload>,
) -> Result<(StatusCode, Json<Value>), ApiError> {
    let subject = grant_subject(&principal);
    input.requested_by = subject.clone();
    input.session_id = principal.session_id.clone();
    let resource = format!("flow://{}/workloads", input.application_id);
    workload_decision(
        &state,
        subject,
        &input.tenant_id,
        &input.application_id,
        resource,
        "workload:create",
        &input.authorization_snapshot,
    )?;
    let workload = state
        .workloads
        .lock()
        .map_err(|_| {
            ApiError(
                StatusCode::INTERNAL_SERVER_ERROR,
                "workload store unavailable".into(),
            )
        })?
        .create(input)
        .map_err(workload_error)?;
    record_authorization_audit(
        &state,
        &principal.key_id,
        "workload.created",
        &workload.workload_id,
        "ready",
        201,
    );
    Ok((StatusCode::CREATED, Json(json!(workload))))
}
async fn list_workloads(
    State(state): State<AppState>,
    Extension(principal): Extension<Principal>,
    Query(target): Query<WorkloadListTarget>,
) -> Result<Json<Value>, ApiError> {
    let tenant = application_scope(
        &state,
        &principal.key_id,
        &target.application_id,
        "workload:read",
    )?;
    let values = state
        .workloads
        .lock()
        .map_err(|_| {
            ApiError(
                StatusCode::INTERNAL_SERVER_ERROR,
                "workload store unavailable".into(),
            )
        })?
        .list(&tenant, &target.application_id);
    Ok(Json(json!({"workloads":values,"grant_id":target.grant_id})))
}
async fn get_workload(
    State(state): State<AppState>,
    Extension(principal): Extension<Principal>,
    Path(id): Path<String>,
) -> Result<Json<Value>, ApiError> {
    let workload = state
        .workloads
        .lock()
        .map_err(|_| {
            ApiError(
                StatusCode::INTERNAL_SERVER_ERROR,
                "workload store unavailable".into(),
            )
        })?
        .get(&id)
        .map_err(workload_error)?
        .clone();
    application_scope(
        &state,
        &principal.key_id,
        &workload.application_id,
        "workload:read",
    )?;
    Ok(Json(json!(workload)))
}
async fn claim_workload(
    State(state): State<AppState>,
    Extension(principal): Extension<Principal>,
    Path(id): Path<String>,
    Json(input): Json<WorkloadClaimRequest>,
) -> Result<Json<Value>, ApiError> {
    let workload = state
        .workloads
        .lock()
        .unwrap()
        .get(&id)
        .map_err(workload_error)?
        .clone();
    let subject = grant_subject(&principal);
    if subject != GrantSubject::Worker(input.worker_id.clone()) {
        return Err(ApiError(
            StatusCode::FORBIDDEN,
            "authenticated worker identity does not match claim".into(),
        ));
    }
    workload_decision(
        &state,
        subject,
        &workload.tenant_id,
        &workload.application_id,
        format!("flow://{}/workloads/{}", workload.application_id, id),
        "workload:claim",
        &input.grant,
    )?;
    let claim = {
        let mut mesh = state.mesh.lock().map_err(|_| {
            ApiError(
                StatusCode::INTERNAL_SERVER_ERROR,
                "mesh store unavailable".into(),
            )
        })?;
        let mut workloads = state.workloads.lock().map_err(|_| {
            ApiError(
                StatusCode::INTERNAL_SERVER_ERROR,
                "workload store unavailable".into(),
            )
        })?;
        mesh.place_and_claim(
            &mut workloads,
            &id,
            &input.worker_id,
            unix_seconds_i64(),
            input.lease_ms,
        )
        .map_err(worker_error)?
    };
    Ok(Json(json!(claim)))
}
fn authorize_fence(
    state: &AppState,
    principal: &Principal,
    id: &str,
    fence: &WorkloadFenceRequest,
    capability: &str,
) -> Result<(), ApiError> {
    let workload = state
        .workloads
        .lock()
        .unwrap()
        .get(id)
        .map_err(workload_error)?
        .clone();
    let subject = grant_subject(principal);
    if subject != GrantSubject::Worker(fence.worker_id.clone()) {
        return Err(ApiError(
            StatusCode::FORBIDDEN,
            "worker identity mismatch".into(),
        ));
    }
    workload_decision(
        state,
        subject,
        &workload.tenant_id,
        &workload.application_id,
        format!("flow://{}/workloads/{id}", workload.application_id),
        capability,
        &fence.grant,
    )?;
    Ok(())
}
