fn authorize_worker_action(
    state: &AppState,
    principal: &Principal,
    id: &str,
    grant: &feltdb::authorization::SignedGrant,
    capability: &str,
) -> Result<feltdb::worker_mesh::Worker, ApiError> {
    let worker = state
        .mesh
        .lock()
        .unwrap()
        .workers
        .get(id)
        .cloned()
        .ok_or_else(|| ApiError(StatusCode::NOT_FOUND, "worker not found".into()))?;
    let subject = grant_subject(principal);
    if matches!(subject, GrantSubject::Worker(_)) && subject != GrantSubject::Worker(id.into()) {
        return Err(ApiError(
            StatusCode::FORBIDDEN,
            "worker identity mismatch".into(),
        ));
    }
    workload_decision(
        state,
        subject,
        &worker.tenant_id,
        &worker.application_id,
        format!("flow://{}/workers/{id}", worker.application_id),
        capability,
        grant,
    )?;
    Ok(worker)
}
