fn control_error(error: String) -> ApiError {
    if error == "forbidden" {
        ApiError(StatusCode::FORBIDDEN, error)
    } else {
        ApiError(StatusCode::BAD_REQUEST, error)
    }
}
fn is_platform_owner(principal: &Principal) -> bool {
    let identity = match principal.identity_id.as_deref() {
        Some(identity) => identity.trim().to_lowercase(),
        None => return false,
    };
    std::env::var("FELTDB_PLATFORM_OWNERS")
        .unwrap_or_default()
        .split(',')
        .map(|owner| owner.trim().to_lowercase())
        .any(|owner| !owner.is_empty() && owner == identity)
}
fn require_platform_owner(principal: &Principal) -> Result<(), ApiError> {
    is_platform_owner(principal).then_some(()).ok_or(ApiError(
        StatusCode::FORBIDDEN,
        "platform owner access required".into(),
    ))
}
async fn platform_access(Extension(principal): Extension<Principal>) -> Json<Value> {
    let platform_role = is_platform_owner(&principal).then_some("super_owner");
    Json(json!({
        "identity": principal.identity_id,
        "platform_role": platform_role,
        "capabilities": if platform_role.is_some() {
            vec!["platform:admin", "platform:users:manage", "platform:data:manage"]
        } else {
            Vec::<&str>::new()
        },
    }))
}
async fn platform_overview(
    State(state): State<AppState>,
    Extension(principal): Extension<Principal>,
) -> Result<Json<Value>, ApiError> {
    require_platform_owner(&principal)?;
    let (users, tenants, applications, tenant_memberships, application_memberships) =
        state.tenancy.platform_inventory().map_err(control_error)?;
    let identities = state.identities.list().map_err(control_error)?;
    let runtime_metrics = state.metrics.snapshot();
    Ok(Json(json!({
        "owner": principal.identity_id,
        "users": users,
        "tenants": tenants,
        "applications": applications,
        "tenant_memberships": tenant_memberships,
        "application_memberships": application_memberships,
        "identities": identities,
        "adoption": {
            "measured_at": unix_seconds_i64().max(0) as u64,
            "runtime_process_started_seconds_ago": state.started_at.elapsed().as_secs(),
            "runtime": runtime_metrics,
        },
    })))
}
