async fn create_artifact(
    State(state): State<AppState>,
    Extension(principal): Extension<Principal>,
    Query(input): Query<CreateArtifactQuery>,
    body: Bytes,
) -> Result<(StatusCode, Json<Value>), ApiError> {
    if body.is_empty() {
        return Err(ApiError(
            StatusCode::BAD_REQUEST,
            "artifact content must not be empty".into(),
        ));
    }
    let producer = ProducerRef {
        kind: input.producer_kind,
        id: if input.producer_id.is_empty() {
            principal.key_id.clone()
        } else {
            input.producer_id
        },
    };
    let metadata = ArtifactMetadata {
        name: input.name,
        ..Default::default()
    };
    let artifact = state
        .artifacts
        .create(
            &principal.key_id,
            &state.tenancy,
            &input.application_id,
            input.kind,
            input.content_type,
            &body,
            producer,
            input.parents,
            input.supersedes,
            metadata,
            input.revision,
            input.workload,
            input.execution,
        )
        .map_err(control_error)?;
    Ok((StatusCode::CREATED, Json(json!(artifact))))
}
