async fn export_bundle(
    State(state): State<AppState>,
    Extension(principal): Extension<Principal>,
    Json(input): Json<ExportBundleRequest>,
) -> Result<(StatusCode, Json<Value>), ApiError> {
    let tenant = application_scope(
        &state,
        &principal.key_id,
        &input.application_id,
        "applications:read",
    )?;
    let revisions = state.applications.revisions(&tenant, &input.application_id);
    let latest = revisions.first().ok_or_else(|| {
        ApiError(
            StatusCode::NOT_FOUND,
            "application has no committed revision".into(),
        )
    })?;
    let manifest = serde_json::to_value(&latest.manifest)
        .map_err(|e| ApiError(StatusCode::INTERNAL_SERVER_ERROR, e.to_string()))?;
    let selected = if input.options.include_history {
        revisions
    } else {
        vec![latest.clone()]
    };
    let revision_values = selected
        .iter()
        .map(serde_json::to_value)
        .collect::<Result<Vec<_>, _>>()
        .map_err(|e| ApiError(StatusCode::INTERNAL_SERVER_ERROR, e.to_string()))?;
    let state_value = if input.options.include_data {
        Some(
            serde_json::to_value(state.db.export_snapshot()?)
                .map_err(|e| ApiError(StatusCode::INTERNAL_SERVER_ERROR, e.to_string()))?,
        )
    } else {
        None
    };
    let mut bundle_artifacts = Vec::new();
    if input.options.include_artifacts {
        for artifact in state
            .artifacts
            .list(&principal.key_id, &state.tenancy, &input.application_id)
            .map_err(control_error)?
        {
            let content = state
                .artifacts
                .content(&principal.key_id, &state.tenancy, &artifact.id)
                .map_err(control_error)?;
            bundle_artifacts.push(BundleArtifact {
                manifest: serde_json::to_value(artifact)
                    .map_err(|e| ApiError(StatusCode::INTERNAL_SERVER_ERROR, e.to_string()))?,
                content_base64: base64::engine::general_purpose::STANDARD.encode(content),
            });
        }
    }
    let connections = state
        .connections
        .list_connections(&principal.key_id, &state.tenancy, &input.application_id)
        .map_err(control_error)?
        .iter()
        .map(serde_json::to_value)
        .collect::<Result<Vec<_>, _>>()
        .map_err(|e| ApiError(StatusCode::INTERNAL_SERVER_ERROR, e.to_string()))?;
    let bundle = PortableBundle::build(
        tenant,
        input.application_id,
        manifest,
        revision_values,
        state_value,
        bundle_artifacts,
        connections,
        input.options,
    )
    .map_err(control_error)?;
    state.bundles.put(bundle.clone()).map_err(control_error)?;
    Ok((StatusCode::CREATED, Json(json!(bundle))))
}
