async fn apply_bundle_import(
    State(state): State<AppState>,
    Extension(principal): Extension<Principal>,
    Json(input): Json<ImportBundleRequest>,
) -> Result<(StatusCode, Json<Value>), ApiError> {
    input.bundle.verify().map_err(control_error)?;
    let app = input.destination_application.clone().ok_or_else(|| {
        ApiError(
            StatusCode::BAD_REQUEST,
            "destination_application is required".into(),
        )
    })?;
    application_scope(&state, &principal.key_id, &app, "applications:write")?;
    let plan = input
        .bundle
        .plan(
            input.mode,
            input.destination_tenant.clone(),
            Some(app.clone()),
        )
        .map_err(control_error)?;
    let manifest_text = serde_json::to_string(&input.bundle.manifest)
        .map_err(|e| ApiError(StatusCode::BAD_REQUEST, e.to_string()))?;
    let legacy = json!({"format":"feltdb-app/v1","files":{"manifest.json":manifest_text},"checksums":{"manifest.json":format!("sha256:{:x}",Sha256::digest(serde_json::to_string(&input.bundle.manifest).unwrap_or_default().as_bytes()))}});
    let draft = state
        .applications
        .import_draft(
            &input.destination_tenant,
            &app,
            "Imported bundle",
            &principal.key_id,
            &legacy,
        )
        .map_err(control_error)?;
    let revision = state
        .applications
        .commit(
            &input.destination_tenant,
            &app,
            &draft.draft_id,
            &principal.key_id,
        )
        .map_err(control_error)?;
    Ok((
        StatusCode::CREATED,
        Json(
            json!({"applied":true,"plan":plan,"revision":revision,"security_authority_imported":false}),
        ),
    ))
}
