async fn plan_deployment(
    State(state): State<AppState>,
    Extension(principal): Extension<Principal>,
    Json(input): Json<DeploymentPlanRequest>,
) -> Result<Json<Value>, ApiError> {
    let release = state
        .releases
        .get(&input.release_id)
        .ok_or_else(|| ApiError(StatusCode::NOT_FOUND, "release not found".into()))?;
    application_scope(
        &state,
        &principal.key_id,
        &release.manifest.application_id,
        "applications:read",
    )?;
    let mut plan = state
        .releases
        .plan_for(
            &input.release_id,
            &input.environment,
            input.provider,
            input.profile,
            input.rollback_target,
        )
        .map_err(control_error)?;
    plan.configuration = input.configuration;
    plan.domains = input.domains;
    plan.secret_references = input.secret_references;
    plan.required_secrets = plan
        .secret_references
        .iter()
        .map(|reference| reference.name.clone())
        .collect();
    plan.scaling_policy = input.scaling_policy;
    provider_for(plan.provider)
        .validate(&plan)
        .map_err(control_error)?;
    Ok(Json(json!(plan)))
}
async fn deploy_release(
    State(state): State<AppState>,
    Extension(principal): Extension<Principal>,
    Json(input): Json<DeployRequest>,
) -> Result<(StatusCode, Json<Value>), ApiError> {
    let tenant_id = application_scope(
        &state,
        &principal.key_id,
        &input.plan.application_id,
        "deployment:execute",
    )?;
    let deployment_id = next_id(&state, "deployment");
    let references: Vec<_> = input
        .plan
        .secret_references
        .iter()
        .map(|reference| (reference.name.clone(), reference.provider_reference.clone()))
        .collect();
    let plan = input.plan;
    let deployment = state
        .connections
        .with_deployment_secrets(
            &principal.key_id,
            &state.tenancy,
            &plan.application_id,
            &deployment_id,
            &format!("{:?}", plan.provider),
            &references,
            "deploy",
            |values, versions| {
                let credentials = values
                    .iter()
                    .map(|(name, value)| {
                        String::from_utf8(value.clone())
                            .map(|text| (name.clone(), text))
                            .map_err(|_| "deployment credential is not UTF-8")
                    })
                    .collect::<Result<_, _>>()?;
                let versions = versions
                    .iter()
                    .map(|(name, version)| (name.clone(), *version))
                    .collect();
                let context = AuthorizedDeploymentContext::new(
                    tenant_id.clone(),
                    &plan,
                    deployment_id.clone(),
                    principal.key_id.clone(),
                    credentials,
                    versions,
                );
                let provider = provider_for(plan.provider);
                state
                    .releases
                    .deploy_authorized(plan.clone(), provider.as_ref(), context)
            },
        )
        .map_err(control_error)?
        .map_err(control_error)?;
    Ok((StatusCode::CREATED, Json(json!(deployment))))
}
