fn execute_deployment_operation<T>(
    state: &AppState,
    principal: &Principal,
    deployment: &feltdb_server::releases::Deployment,
    operation: &str,
    execute: impl FnOnce(&dyn DeploymentProvider, AuthorizedDeploymentContext) -> Result<T, String>,
) -> Result<T, ApiError> {
    let tenant_id = application_scope(
        state,
        &principal.key_id,
        &deployment.plan.application_id,
        "deployment:execute",
    )?;
    let references: Vec<_> = deployment
        .plan
        .secret_references
        .iter()
        .map(|reference| (reference.name.clone(), reference.provider_reference.clone()))
        .collect();
    state
        .connections
        .with_deployment_secrets(
            &principal.key_id,
            &state.tenancy,
            &deployment.plan.application_id,
            &deployment.deployment_id,
            &format!("{:?}", deployment.plan.provider),
            &references,
            operation,
            |values, versions| {
                let credentials = values
                    .iter()
                    .map(|(name, value)| {
                        String::from_utf8(value.clone())
                            .map(|text| (name.clone(), text))
                            .map_err(|_| "deployment credential is not UTF-8")
                    })
                    .collect::<Result<_, _>>()?;
                let versions = versions
                    .iter()
                    .map(|(name, version)| (name.clone(), *version))
                    .collect();
                let mut context = AuthorizedDeploymentContext::new(
                    tenant_id,
                    &deployment.plan,
                    deployment.deployment_id.clone(),
                    principal.key_id.clone(),
                    credentials,
                    versions,
                );
                context.desired_state = deployment.desired_state;
                let provider = provider_for(deployment.plan.provider);
                execute(provider.as_ref(), context)
            },
        )
        .map_err(control_error)?
        .map_err(control_error)
}
