fn application_scope(
    state: &AppState,
    actor: &str,
    application_id: &str,
    capability: &str,
) -> Result<String, ApiError> {
    let tenant_id = state
        .tenancy
        .application_tenant(application_id)
        .ok_or(ApiError(
            StatusCode::NOT_FOUND,
            "application not found".into(),
        ))?;
    if std::env::var("FELTDB_INTENT_AUTHORITY_KEY_ID").as_deref() == Ok(actor) {
        return Ok(tenant_id);
    }
    if !state
        .tenancy
        .authorize_application(actor, &tenant_id, application_id, capability)
    {
        return Err(ApiError(StatusCode::FORBIDDEN, "forbidden".into()));
    }
    Ok(tenant_id)
}
fn manifest_error(error: String) -> ApiError {
    if let Some(version) = error.strip_prefix("version_conflict:") {
        ApiError(
            StatusCode::CONFLICT,
            format!("draft was changed; current version is {version}"),
        )
    } else if error.starts_with("expected_revision_mismatch:") {
        ApiError(StatusCode::CONFLICT, error)
    } else if error.ends_with("not found") {
        ApiError(StatusCode::NOT_FOUND, error)
    } else {
        ApiError(StatusCode::BAD_REQUEST, error)
    }
}
async fn create_application_draft(
    State(state): State<AppState>,
    Extension(principal): Extension<Principal>,
    Path(application_id): Path<String>,
    Json(input): Json<CreateDraftRequest>,
) -> Result<(StatusCode, Json<Value>), ApiError> {
    let tenant = application_scope(
        &state,
        &principal.key_id,
        &application_id,
        "application:revision:create",
    )?;
    let app = state
        .tenancy
        .application_for(&principal.key_id, &application_id)
        .ok_or(ApiError(
            StatusCode::NOT_FOUND,
            "application not found".into(),
        ))?;
    let draft = state
        .applications
        .create_draft(
            &tenant,
            &application_id,
            &app.name,
            &principal.key_id,
            input.base_revision_id.as_deref(),
        )
        .map_err(manifest_error)?;
    Ok((StatusCode::CREATED, Json(json!(draft))))
}
