fn draft_contract(
    state: &AppState,
    actor: &str,
    application_id: &str,
    draft_id: &str,
) -> Result<ApplicationRuntimeContract, ApiError> {
    let tenant = application_scope(state, actor, application_id, "application:revision:create")?;
    let draft = state
        .applications
        .get_draft(&tenant, application_id, draft_id)
        .ok_or(ApiError(StatusCode::NOT_FOUND, "draft not found".into()))?;
    let revision = feltdb::application::draft_as_revision(&draft).map_err(manifest_error)?;
    let inventory = runtime_inventory(state, actor, application_id, &revision.manifest)?;
    resolve_runtime(&revision, "preview", &inventory).map_err(|report| {
        ApiError(
            StatusCode::CONFLICT,
            serde_json::to_string(&report).unwrap_or_else(|_| "runtime validation failed".into()),
        )
    })
}
