async fn commit_application_draft(
    State(state): State<AppState>,
    Extension(principal): Extension<Principal>,
    Path((application_id, draft_id)): Path<(String, String)>,
) -> Result<(StatusCode, Json<Value>), ApiError> {
    let tenant = application_scope(
        &state,
        &principal.key_id,
        &application_id,
        "application:revision:create",
    )?;
    let revision = state
        .applications
        .commit(&tenant, &application_id, &draft_id, &principal.key_id)
        .map_err(manifest_error)?;
    let encoded_revision = percent_encode_path_segment(&revision.revision_id);
    let mut response = serde_json::to_value(revision)
        .map_err(|error| ApiError(StatusCode::INTERNAL_SERVER_ERROR, error.to_string()))?;
    response
        .as_object_mut()
        .expect("application revisions serialize as objects")
        .insert(
            "promotion".into(),
            json!({
                "status": "ready",
                "url": format!(
                    "/api/applications/{application_id}/revisions/{encoded_revision}/promote"
                ),
            }),
        );
    Ok((StatusCode::CREATED, Json(response)))
}

fn percent_encode_path_segment(value: &str) -> String {
    value
        .bytes()
        .flat_map(|byte| {
            if byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_' | b'.' | b'~') {
                vec![byte as char]
            } else {
                format!("%{byte:02X}").chars().collect()
            }
        })
        .collect()
}
