async fn preview_application_revision(
    State(state): State<AppState>,
    Extension(principal): Extension<Principal>,
    Path((application_id, revision_id)): Path<(String, String)>,
    Json(input): Json<PreviewRevisionRequest>,
) -> Result<(StatusCode, Json<Value>), ApiError> {
    let tenant = application_scope(
        &state,
        &principal.key_id,
        &application_id,
        "application:revision:preview",
    )?;
    let revision = state
        .applications
        .revision(&tenant, &application_id, &revision_id)
        .ok_or(ApiError(StatusCode::NOT_FOUND, "revision not found".into()))?;
    let mut inventory = runtime_inventory(
        &state,
        &principal.key_id,
        &application_id,
        &revision.manifest,
    )?;
    if input.policy.connections == PreviewDataMode::Empty {
        inventory.connections.clear();
    }
    let preview_environment = format!("preview/{}", principal.key_id);
    let readiness = runtime_readiness(&revision, &preview_environment, &inventory);
    if readiness.status == ReadinessStatus::Blocked {
        return Err(ApiError(
            StatusCode::CONFLICT,
            serde_json::to_string(&readiness).unwrap_or_default(),
        ));
    }
    let preview = state
        .applications
        .create_preview(
            &tenant,
            &application_id,
            &revision_id,
            &principal.key_id,
            input.policy,
        )
        .map_err(manifest_error)?;
    let contract = resolve_runtime(&revision, &preview.environment, &inventory).map_err(|v| {
        ApiError(
            StatusCode::CONFLICT,
            serde_json::to_string(&v).unwrap_or_default(),
        )
    })?;
    let seeded_records = if matches!(
        preview.policy.state,
        PreviewDataMode::Snapshot | PreviewDataMode::Cloned
    ) {
        if let Some(base) = preview.based_on_revision.as_deref() {
            let source = revision_contract(
                &state,
                &principal.key_id,
                &application_id,
                base,
                "production",
            )?;
            snapshot_state_namespace(
                &state.db,
                &source.environment.state_namespace,
                &contract.environment.state_namespace,
            )
            .map_err(manifest_error)?
        } else {
            0
        }
    } else {
        0
    };
    let runtime = state
        .runtimes
        .start(&contract, &principal.key_id)
        .map_err(manifest_error)?;
    Ok((
        StatusCode::CREATED,
        Json(
            json!({"preview":preview,"readiness":readiness,"runtime":runtime,"contract":contract,"seeded_records":seeded_records}),
        ),
    ))
}
async fn get_application_preview(
    State(state): State<AppState>,
    Extension(principal): Extension<Principal>,
    Path((application_id, preview_id)): Path<(String, String)>,
) -> Result<Json<Value>, ApiError> {
    let tenant = application_scope(
        &state,
        &principal.key_id,
        &application_id,
        "application:revision:read",
    )?;
    let preview = state
        .applications
        .preview(&tenant, &application_id, &preview_id)
        .ok_or(ApiError(StatusCode::NOT_FOUND, "preview not found".into()))?;
    let runtime = state.runtimes.active(
        &tenant,
        &application_id,
        &preview.revision_id,
        &preview.environment,
    );
    let executions = state
        .db
        .export_snapshot()?
        .rows
        .into_iter()
        .filter(|row| {
            !row.deleted
                && row.capability.contains("_runtime_workflow_runs")
                && row.value.get("revision_id").and_then(Value::as_str)
                    == Some(preview.revision_id.as_str())
        })
        .map(|row| row.value)
        .collect::<Vec<_>>();
    Ok(Json(
        json!({"preview":preview,"runtime":runtime,"executions":executions}),
    ))
}
