#[allow(clippy::too_many_arguments)]
fn move_environment(
    state: &AppState,
    principal: &Principal,
    application_id: &str,
    environment: &str,
    revision_id: &str,
    expected: Option<&str>,
    reason: &str,
    approved: bool,
    rollback: bool,
) -> Result<Value, ApiError> {
    let capability = if rollback {
        "application:revision:rollback"
    } else {
        "application:revision:promote"
    };
    let tenant = application_scope(state, &principal.key_id, application_id, capability)?;
    let revision = state
        .applications
        .revision(&tenant, application_id, revision_id)
        .ok_or(ApiError(StatusCode::NOT_FOUND, "revision not found".into()))?;
    let inventory =
        runtime_inventory(state, &principal.key_id, application_id, &revision.manifest)?;
    let readiness = runtime_readiness(&revision, environment, &inventory);
    if readiness.status == ReadinessStatus::Blocked {
        return Err(ApiError(
            StatusCode::CONFLICT,
            serde_json::to_string(&readiness).unwrap_or_default(),
        ));
    }
    let promotion = state
        .applications
        .move_environment_pointer(
            &tenant,
            application_id,
            revision_id,
            environment,
            expected,
            &principal.key_id,
            reason,
            approved,
            rollback,
        )
        .map_err(manifest_error)?;
    Ok(json!({"promotion":promotion,"readiness":readiness}))
}
