fn runtime_inventory(
    state: &AppState,
    _actor: &str,
    application_id: &str,
    manifest: &ApplicationManifest,
) -> Result<RuntimeInventory, ApiError> {
    let connections = state
        .connections
        .application_connections(application_id)
        .map_err(control_error)?;
    let connection_ids = connections
        .into_iter()
        .filter(|value| value.status == ConnectionStatus::Active)
        .map(|value| value.id)
        .collect();
    let snapshot = state.db.export_snapshot()?;
    let mut capabilities = BTreeSet::new();
    for row in snapshot
        .rows
        .iter()
        .filter(|row| row.capability == "_flow_capabilities" && !row.deleted)
    {
        if let Some(name) = row.value.get("name").and_then(Value::as_str) {
            capabilities.insert(name.to_string());
        } else if let Some((_, name)) = row.key.rsplit_once(':') {
            capabilities.insert(name.to_string());
        }
    }
    for binding in manifest
        .capabilities
        .iter()
        .filter(|binding| binding.provider.is_none())
    {
        capabilities.insert(binding.name.clone());
    }
    Ok(RuntimeInventory {
        capabilities,
        connections: connection_ids,
        enforce_availability: true,
    })
}
