async fn run_runtime_action(
    State(state): State<AppState>,
    Extension(principal): Extension<Principal>,
    Path((application_id, revision_id, action)): Path<(String, String, String)>,
    Query(environment): Query<RuntimeEnvironmentRequest>,
    Json(input): Json<Value>,
) -> Result<Json<Value>, ApiError> {
    application_scope(&state, &principal.key_id, &application_id, "state:write")?;
    let contract = revision_contract(
        &state,
        &principal.key_id,
        &application_id,
        &revision_id,
        &environment.environment,
    )?;
    let tenant = contract.tenant_id.clone();
    if state
        .runtimes
        .active(
            &tenant,
            &application_id,
            &contract.revision_id,
            &environment.environment,
        )
        .is_none()
    {
        return Err(ApiError(
            StatusCode::CONFLICT,
            "runtime is not running".into(),
        ));
    }
    let definition = contract
        .actions
        .definitions
        .iter()
        .find(|value| value.name == action)
        .ok_or(ApiError(StatusCode::NOT_FOUND, "action not found".into()))?;
    for capability in &definition.required_capabilities {
        if !state.tenancy.authorize_application(
            &principal.key_id,
            &tenant,
            &application_id,
            capability,
        ) {
            return Err(ApiError(
                StatusCode::FORBIDDEN,
                format!("missing action capability: {capability}"),
            ));
        }
    }
    let mut value = input;
    let object = value.as_object_mut().ok_or(ApiError(
        StatusCode::UNPROCESSABLE_ENTITY,
        "action input must be an object".into(),
    ))?;
    let explicit_id = object
        .remove("id")
        .and_then(|value| value.as_str().map(str::to_string));
    let if_version = object
        .remove("if_version")
        .or_else(|| object.remove("_version"))
        .and_then(|value| value.as_u64());
    let id = explicit_id.unwrap_or_else(|| {
        let digest = Sha256::digest(serde_json::to_vec(&value).unwrap_or_default());
        format!("record_{:x}", digest)[..31].to_string()
    });
    let kind = match definition.operation {
        ActionOperation::Create => TransactionOperationKind::Insert,
        ActionOperation::Update => TransactionOperationKind::Update,
        ActionOperation::Delete => TransactionOperationKind::Delete,
    };
    if !matches!(kind, TransactionOperationKind::Insert) && id.starts_with("record_") {
        return Err(ApiError(
            StatusCode::UNPROCESSABLE_ENTITY,
            "update and delete actions require id".into(),
        ));
    }
    let request = TransactionRequest {
        transaction_id: None,
        tenant_id: tenant.clone(),
        application_id: application_id.clone(),
        revision_id: contract.revision_id.clone(),
        schema_version: contract.state.schema.schema_version,
        state_namespace: Some(contract.environment.state_namespace.clone()),
        causal_parent: None,
        authorization: state_authorization(&principal, &contract, &definition.collection, "write"),
        operations: vec![TransactionOperation {
            kind,
            collection: definition.collection.clone(),
            id,
            value,
            if_version,
        }],
        preconditions: vec![],
    };
    let write_policy = contract
        .policies
        .definitions
        .iter()
        .find(|p| p.resource == definition.collection)
        .and_then(|p| p.write.as_ref().and_then(|s| PolicySubject::from_str(s)));
    let _transaction_permit = state
        .state_transaction_admission
        .acquire()
        .await
        .expect("transaction admission is never closed");
    Ok(Json(json!(execute_transaction(
        &state.db,
        &contract.state.schema,
        &request,
        write_policy
    )
    .map_err(state_contract_error)?)))
}
