async fn run_runtime_query(
    State(state): State<AppState>,
    Extension(principal): Extension<Principal>,
    Path((application_id, revision_id, query)): Path<(String, String, String)>,
    Query(environment): Query<RuntimeEnvironmentRequest>,
) -> Result<Json<Value>, ApiError> {
    application_scope(&state, &principal.key_id, &application_id, "state:read")?;
    let contract = revision_contract(
        &state,
        &principal.key_id,
        &application_id,
        &revision_id,
        &environment.environment,
    )?;
    if state
        .runtimes
        .active(
            &contract.tenant_id,
            &application_id,
            &contract.revision_id,
            &environment.environment,
        )
        .is_none()
    {
        return Err(ApiError(
            StatusCode::CONFLICT,
            "runtime is not running".into(),
        ));
    }
    let definition = contract
        .queries
        .definitions
        .iter()
        .find(|value| value.name == query)
        .ok_or(ApiError(StatusCode::NOT_FOUND, "query not found".into()))?;
    let filter = definition
        .filter
        .as_object()
        .map(|fields| QueryFilter::And {
            filters: fields
                .iter()
                .map(|(field, value)| QueryFilter::Eq {
                    field: field.clone(),
                    value: value.clone(),
                })
                .collect(),
        });
    let query = CanonicalQuery {
        collection: definition.collection.clone(),
        filter,
        order_by: vec![],
        limit: Some(100),
        offset: 0,
        cursor: None,
        projection: definition.fields.clone(),
        group_by: vec![],
        aggregates: vec![],
        references: vec![],
    };
    let context = feltdb::state_contract::begin_query_read(
        &state.db,
        &contract.state.schema,
        &contract.environment.state_namespace,
        state_authorization(&principal, &contract, &definition.collection, "read"),
    )
    .map_err(state_contract_error)?;

    // Look up the read policy for record-level authorization
    let read_policy = contract
        .policies
        .definitions
        .iter()
        .find(|p| p.resource == definition.collection)
        .and_then(|p| p.read.as_ref().and_then(|s| PolicySubject::from_str(s)));

    Ok(Json(json!(execute_state_query(
        &state.db,
        &contract.state.schema,
        &context,
        &query,
        read_policy
    )
    .map_err(state_contract_error)?)))
}
