fn state_policy_resource_matches(resource: &str, collection: &str) -> bool {
    resource == collection
        || resource
            .strip_suffix('*')
            .is_some_and(|prefix| !prefix.contains('*') && collection.starts_with(prefix))
}
fn matching_state_policy<'a>(
    contract: &'a ApplicationRuntimeContract,
    collection: &str,
) -> Option<&'a feltdb::application::PolicyDefinition> {
    contract
        .policies
        .definitions
        .iter()
        .find(|p| p.resource == collection)
        .or_else(|| {
            contract
                .policies
                .definitions
                .iter()
                .find(|p| state_policy_resource_matches(&p.resource, collection))
        })
}
fn authorize_transaction_collections(
    principal: &Principal,
    contract: &ApplicationRuntimeContract,
    tenant: &str,
    collections: &[String],
) -> (bool, BTreeMap<String, PolicySubject>) {
    if tenant != contract.tenant_id || collections.is_empty() {
        return (false, BTreeMap::new());
    }
    let mut write_policies = BTreeMap::new();
    for collection in collections {
        let decision = state_authorization(principal, contract, collection, "write");
        if !decision.capabilities.contains("state:write") {
            return (false, BTreeMap::new());
        }
        if let Some(subject) = matching_state_policy(contract, collection)
            .and_then(|policy| policy.write.as_deref())
            .and_then(PolicySubject::from_str)
        {
            write_policies.insert(collection.clone(), subject);
        }
    }
    (true, write_policies)
}
fn state_authorization(
    principal: &Principal,
    contract: &ApplicationRuntimeContract,
    collection: &str,
    operation: &str, // "read" or "write"
) -> AuthorizationContext {
    let subject = format!("{}:{}", principal.subject_type, principal.key_id);

    let policy = matching_state_policy(contract, collection);
    let policy_subject = policy.and_then(|p| {
        if operation == "read" {
            p.read.as_ref().and_then(|s| PolicySubject::from_str(s))
        } else {
            p.write.as_ref().and_then(|s| PolicySubject::from_str(s))
        }
    });

    // Evaluate policy if found
    let capabilities = if let Some(policy) = policy_subject {
        // Create policy context for evaluation
        let actor = if principal.key_id.is_empty() {
            None
        } else {
            Some(Actor::new(&principal.key_id))
        };
        let context = PolicyContext::new(actor, collection, "");

        // Evaluate policy
        match PolicyEvaluator::evaluate(policy, &context) {
            Ok(_) => {
                // Policy allows access
                let capability = if operation == "read" {
                    "state:read"
                } else {
                    "state:write"
                };
                [capability.into()].into()
            }
            Err(_) => {
                // Policy denies access
                BTreeSet::new()
            }
        }
    } else if policy.is_some_and(|p| {
        p.capabilities.iter().any(|capability| {
            capability
                == if operation == "read" {
                    "state:read"
                } else {
                    "state:write"
                }
        })
    }) {
        let capability = if operation == "read" {
            "state:read"
        } else {
            "state:write"
        };
        [capability.into()].into()
    } else {
        BTreeSet::new()
    };

    AuthorizationContext {
        subject,
        tenant_id: contract.tenant_id.clone(),
        application_id: contract.application_id.clone(),
        revision_id: contract.revision_id.clone(),
        capabilities,
        readable_collections: Default::default(),
        writable_collections: Default::default(),
        field_projections: Default::default(),
    }
}

// Backward-compatible wrapper for call sites without ApplicationRuntimeContract
fn state_authorization_legacy(
    principal: &Principal,
    tenant: &str,
    application: &str,
    revision: &str,
    capability: &str,
) -> AuthorizationContext {
    AuthorizationContext {
        subject: format!("{}:{}", principal.subject_type, principal.key_id),
        tenant_id: tenant.into(),
        application_id: application.into(),
        revision_id: revision.into(),
        capabilities: [capability.into()].into(),
        readable_collections: Default::default(),
        writable_collections: Default::default(),
        field_projections: Default::default(),
    }
}

fn state_contract_error(error: feltdb::state_contract::StateFailure) -> ApiError {
    let status = match error.code.as_str() {
        "AUTHORIZATION_DENIED" => StatusCode::FORBIDDEN,
        "PRECONDITION_FAILED" | "CONFLICT" | "IDEMPOTENCY_CONFLICT" => StatusCode::CONFLICT,
        "UNKNOWN_COLLECTION" => StatusCode::NOT_FOUND,
        "STORAGE_FAILURE" | "STATE_UNAVAILABLE" => StatusCode::SERVICE_UNAVAILABLE,
        _ => StatusCode::UNPROCESSABLE_ENTITY,
    };
    ApiError(
        status,
        serde_json::to_string(&error).unwrap_or(error.message),
    )
}
async fn validate_state_schema(
    State(state): State<AppState>,
    Extension(principal): Extension<Principal>,
    Json(schema): Json<StateSchema>,
) -> Result<Json<Value>, ApiError> {
    application_scope(
        &state,
        &principal.key_id,
        &schema.application_id,
        "application:revision:read",
    )?;
    Ok(Json(json!(validate_schema(&schema))))
}
async fn get_state_schema(
    State(state): State<AppState>,
    Extension(principal): Extension<Principal>,
    Query(target): Query<StateContractTarget>,
) -> Result<Json<Value>, ApiError> {
    let tenant = application_scope(
        &state,
        &principal.key_id,
        &target.application_id,
        "application:revision:read",
    )?;
    let revision = state
        .applications
        .revision(&tenant, &target.application_id, &target.revision_id)
        .ok_or(ApiError(StatusCode::NOT_FOUND, "revision not found".into()))?;
    let schema = schema_from_revision(&revision);
    Ok(Json(
        json!({"schema":schema,"validation":validate_schema(&schema)}),
    ))
}
async fn get_state_version(
    State(state): State<AppState>,
    Extension(principal): Extension<Principal>,
    Query(target): Query<StateContractTarget>,
) -> Result<Json<Value>, ApiError> {
    application_scope(
        &state,
        &principal.key_id,
        &target.application_id,
        "state:read",
    )?;
    let contract = revision_contract(
        &state,
        &principal.key_id,
        &target.application_id,
        &target.revision_id,
        &target.environment,
    )?;
    Ok(Json(
        json!({"application_id":target.application_id,"revision_id":contract.revision_id,"schema_version":contract.state.schema.schema_version,"state_version":state.db.sequence()?,"causal_cursor":state.db.operation_versions()?,"state_namespace":contract.environment.state_namespace}),
    ))
}
fn require_bound_tenant(headers: &HeaderMap, tenant: &str) -> Result<(), ApiError> {
    let Some(bound) = headers.get("feltdb-tenant-id") else { return Ok(()); };
    if bound.to_str().ok() == Some(tenant) { return Ok(()); }
    Err(ApiError(StatusCode::FORBIDDEN, json!({
        "code":"AUTHORITY_SCOPE_MISMATCH",
        "message":"request tenant does not match the authenticated application authority",
        "http_status":403
    }).to_string()))
}

async fn execute_canonical_query(
    State(state): State<AppState>,
    Extension(principal): Extension<Principal>,
    headers: HeaderMap,
    Json(input): Json<CanonicalQueryRequest>,
) -> Result<Json<Value>, ApiError> {
    let tenant = application_scope(
        &state,
        &principal.key_id,
        &input.application_id,
        "state:read",
    )?;
    require_bound_tenant(&headers, &tenant)?;
    let contract = revision_contract(
        &state,
        &principal.key_id,
        &input.application_id,
        &input.revision_id,
        &input.environment,
    )?;
    let context = feltdb::state_contract::begin_query_read(
        &state.db,
        &contract.state.schema,
        &contract.environment.state_namespace,
        state_authorization(&principal, &contract, &input.query.collection, "read"),
    )
    .map_err(state_contract_error)?;

    // Look up the read policy for record-level authorization
    let read_policy = contract
        .policies
        .definitions
        .iter()
        .find(|p| p.resource == input.query.collection)
        .and_then(|p| p.read.as_ref().and_then(|s| PolicySubject::from_str(s)));

    let result = execute_state_query(
        &state.db,
        &contract.state.schema,
        &context,
        &input.query,
        read_policy,
    )
    .map_err(state_contract_error)?;
    audit(
        &state,
        &principal.key_id,
        "query.read",
        &format!("{}@{}", result.query_hash, result.state_version),
        "allowed",
        200,
    );
    Ok(Json(json!(result)))
}

#[derive(serde::Deserialize)]
struct RevisionRecoveryRequest {
    #[serde(rename = "applicationId")]
    application_id: String,
    #[serde(rename = "targetRevision")]
    target_revision: String,
    #[serde(rename = "expectedCurrentRevision")]
    expected_current_revision: String,
    authorization: String,
    actor: String,
    reason: String,
    #[serde(default)]
    environment: Option<String>,
    #[serde(default)]
    #[serde(rename = "recoveryId")]
    recovery_id: Option<String>,
}

#[derive(serde::Serialize, serde::Deserialize)]
struct RevisionRecoveryResponse {
    success: bool,
    #[serde(rename = "pointerMoved")]
    pointer_moved: bool,
    #[serde(rename = "sourceMarkedUntrusted")]
    source_marked_untrusted: bool,
    #[serde(rename = "auditDurable")]
    audit_durable: bool,
    #[serde(rename = "recoveryId")]
    recovery_id: String,
    #[serde(rename = "targetRevision")]
    target_revision: String,
    #[serde(rename = "currentRevision")]
    current_revision: String,
    audit: serde_json::Value,
}

fn revision_recovery_error(
    status: StatusCode,
    code: &str,
    message: String,
    request_id: &str,
    transaction_id: &str,
) -> ApiError {
    ApiError(
        status,
        json!({"code":code,"message":message,"request_id":request_id,
        "transaction_id":transaction_id,"http_status":status.as_u16()})
        .to_string(),
    )
}

async fn execute_revision_recovery(
    State(state): State<AppState>,
    Extension(principal): Extension<Principal>,
    Json(input): Json<RevisionRecoveryRequest>,
) -> Result<Json<RevisionRecoveryResponse>, ApiError> {
    let request_id = uuid::Uuid::new_v4().to_string();
    let transaction_id = input
        .recovery_id
        .clone()
        .unwrap_or_else(|| uuid::Uuid::new_v4().to_string());

    // Validate authorization level
    let auth_level = input.authorization.as_str();

    if !["ELEVATED", "ADMIN", "EMERGENCY"].contains(&auth_level) {
        return Err(revision_recovery_error(
            StatusCode::FORBIDDEN,
            "PERMISSION_DENIED",
            "Recovery requires ELEVATED, ADMIN, or EMERGENCY authorization".into(),
            &request_id,
            &transaction_id,
        ));
    }

    // Validate input
    if input.reason.len() < 10 {
        return Err(revision_recovery_error(
            StatusCode::UNPROCESSABLE_ENTITY,
            "PRECONDITION_FAILED",
            "Recovery reason must be at least 10 characters".into(),
            &request_id,
            &transaction_id,
        ));
    }

    let recovery_id = transaction_id.clone();
    let environment = input
        .environment
        .unwrap_or_else(|| "production".to_string());
    let tenant = application_scope(
        &state,
        &principal.key_id,
        &input.application_id,
        "application:revision:promote",
    )?;
    let recovery = state
        .applications
        .recover_environment_pointer(
            &tenant,
            &input.application_id,
            &environment,
            &input.expected_current_revision,
            &input.target_revision,
            &input.actor,
            &input.reason,
            auth_level,
            &recovery_id,
        )
        .map_err(|message| {
            let (status, code) = if message.starts_with("expected_revision_mismatch")
                || message == "recovery_id_conflict"
            {
                (StatusCode::CONFLICT, "CONFLICT")
            } else if message.contains("not found") {
                (StatusCode::NOT_FOUND, "PRECONDITION_FAILED")
            } else if message.contains("integrity") || message.contains("untrusted") {
                (StatusCode::UNPROCESSABLE_ENTITY, "VALIDATION_FAILED")
            } else {
                (StatusCode::SERVICE_UNAVAILABLE, "STORAGE_FAILURE")
            };
            revision_recovery_error(status, code, message, &request_id, &transaction_id)
        })?;

    // Build response
    let response = RevisionRecoveryResponse {
        success: true,
        pointer_moved: true,
        source_marked_untrusted: true,
        audit_durable: true,
        recovery_id: recovery_id.clone(),
        target_revision: recovery.target_revision.clone(),
        current_revision: recovery.target_revision.clone(),
        audit: json!(recovery),
    };

    // Audit log
    audit(
        &state,
        &principal.key_id,
        "revision.recover",
        &recovery_id,
        "allowed",
        200,
    );

    Ok(Json(response))
}

async fn execute_canonical_transaction(
    State(state): State<AppState>,
    Extension(principal): Extension<Principal>,
    headers: HeaderMap,
    Json(mut input): Json<CanonicalTransactionRequest>,
) -> Result<Json<Value>, ApiError> {
    let tenant = application_scope(
        &state,
        &principal.key_id,
        &input.application_id,
        "state:write",
    )?;
    require_bound_tenant(&headers, &tenant)?;
    let contract = revision_contract(
        &state,
        &principal.key_id,
        &input.application_id,
        &input.revision_id,
        &input.environment,
    )?;
    if !input.transaction.tenant_id.is_empty() && input.transaction.tenant_id != tenant {
        return Err(ApiError(StatusCode::FORBIDDEN, json!({
            "code":"AUTHORITY_SCOPE_MISMATCH",
            "message":"transaction tenant does not match the bound authority",
            "http_status":403
        }).to_string()));
    }
    input.transaction.tenant_id = tenant.clone();
    input.transaction.application_id = input.application_id.clone();
    input.transaction.revision_id = contract.revision_id.clone();
    input.transaction.schema_version = contract.state.schema.schema_version;
    input.transaction.state_namespace = Some(contract.environment.state_namespace.clone());
    let collections = input
        .transaction
        .operations
        .iter()
        .map(|operation| operation.collection.clone())
        .collect::<Vec<_>>();
    let (authorized, write_policies) =
        authorize_transaction_collections(&principal, &contract, &tenant, &collections);
    input.transaction.authorization = state_authorization_legacy(
        &principal,
        &tenant,
        &input.application_id,
        &contract.revision_id,
        if authorized {
            "state:write"
        } else {
            "state:denied"
        },
    );
    let _transaction_permit = state
        .state_transaction_admission
        .acquire()
        .await
        .expect("transaction admission is never closed");
    let result = execute_transaction_with_collection_policies(
        &state.db,
        &contract.state.schema,
        &input.transaction,
        &write_policies,
    )
    .map_err(state_contract_error)?;
    audit(
        &state,
        &principal.key_id,
        "transaction.commit",
        &result.transaction_id,
        "allowed",
        201,
    );
    let attribution = state.db.transaction_attribution(&result.transaction_id)?;
    let mut response = json!(result);
    response["revision_id"] = json!(format!("revision-{}", result.commit_revision));
    response["operation_ids"] = json!(attribution
        .map(|value| value.operation_ids)
        .unwrap_or_default());
    Ok(Json(response))
}

async fn get_cardinality_diagnostic(
    State(state): State<AppState>,
    Path(pattern): Path<String>,
) -> Result<Json<CardinalityDiagnosticResponse>, ApiError> {
    let all_cardinalities = state
        .db
        .list_cardinalities()
        .map_err(|e| ApiError(StatusCode::INTERNAL_SERVER_ERROR, e.to_string()))?;

    let actual_rows = state
        .db
        .diagnostic_row_count(&pattern)
        .map_err(|e| ApiError(StatusCode::INTERNAL_SERVER_ERROR, e.to_string()))?;

    let persisted_capability_keys = state
        .db
        .diagnostic_capability_keys(&pattern)
        .map_err(|e| ApiError(StatusCode::INTERNAL_SERVER_ERROR, e.to_string()))?;

    let matching_keys: Vec<_> = all_cardinalities
        .iter()
        .filter(|(k, _)| k.contains(&pattern))
        .cloned()
        .collect();

    let cardinality_map_keys: Vec<String> = matching_keys.iter().map(|(k, _)| k.clone()).collect();

    let maintained = matching_keys.iter().map(|(_, v)| v).sum::<u64>();

    let now_ms = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_millis() as u64;

    let total_rows: usize = all_cardinalities.iter().map(|(_, v)| *v as usize).sum();
    let zero_cardinality_count = all_cardinalities.iter().filter(|(_, v)| *v == 0).count();
    let total_collections = all_cardinalities.len();

    Ok(Json(CardinalityDiagnosticResponse {
        collection_pattern: pattern,
        actual_row_count: actual_rows,
        maintained_cardinality: maintained,
        mismatch: actual_rows > 0 && maintained == 0,
        cardinality_keys: matching_keys,
        context: CardinalityContext {
            all_cardinalities,
            persisted_capability_keys,
            cardinality_map_keys,
            timestamp_ms: now_ms,
            total_collections,
            zero_cardinality_count,
            total_rows,
        },
    }))
}

